import collections.abc
import dataclasses
import typing
import urllib.parse


@dataclasses.dataclass
class Netloc:
    """A model representing network location component of the endpoint."""
    host: typing.Optional[str] = None
    port: typing.Optional[int] = None

    def require_host_port(self) -> typing.Tuple[str, int]:
        if self.host is None or self.port is None:
            raise ValueError('host or port is missing')
        return self.host, self.port


class Query(collections.abc.Mapping):
    """An accessor to query parameters of the URL."""

    def __init__(self, **params: typing.List[str]):
        self._params = params

    def __iter__(self):
        return iter(self._params)

    def __len__(self) -> int:
        return len(self._params)

    def __getitem__(self, key):
        return self._params[key]

    def getfirst(self, key, default=None):
        if key not in self:
            return default
        values = self[key]
        if values is not None:
            return values[0]


@dataclasses.dataclass
class Endpoint:
    """A model representing communication endpoint."""
    scheme: typing.Optional[str] = None
    netloc: typing.Optional[Netloc] = None
    path: typing.Optional[str] = None
    query: typing.Optional[Query] = None


def dump_to_url(endpoint: Endpoint) -> str:
    """Convert given *endpoint* object into URL address.

    :param endpoint:
        An endpoint to be converted.
    """

    def iter_query_string(query: Query):
        for name, values in query.items():
            for value in values:
                yield f"{urllib.parse.quote(name, encoding='utf-8')}={urllib.parse.quote(value, encoding='utf-8')}"

    parts = []
    if endpoint.scheme is not None:
        parts.append(endpoint.scheme + '://')
    if endpoint.netloc is not None:
        if endpoint.netloc.host is not None:
            parts.append(endpoint.netloc.host)
        if endpoint.netloc.port is not None:
            parts.append(f':{endpoint.netloc.port}')
    if endpoint.path is not None:
        parts.append(endpoint.path)
    if endpoint.query is not None:
        parts.append(f"?{'&'.join(iter_query_string(endpoint.query))}")
    return ''.join(parts)


def load_from_url(url: str) -> Endpoint:
    """Create new instance of :class:`Endpoint` class from given URL
    address.

    :param url:
        Source URL.
    """
    obj = Endpoint()
    parts = urllib.parse.urlparse(url)
    if parts.scheme:
        obj.scheme = parts.scheme
    if parts.netloc:
        tmp = parts.netloc.split(':', 1)
        if len(tmp) == 1:
            obj.netloc = Netloc(tmp[0])
        else:
            obj.netloc = Netloc(tmp[0], int(tmp[1]))
    if parts.path:
        obj.path = parts.path
    if parts.query:
        tmp = urllib.parse.parse_qs(parts.query)
        obj.query = Query(**tmp)
    return obj
